@import "tailwindcss";

/* Design system: frontend/DESIGN.md ("editorial broadsheet in a green room").
   Light only. Green is the single chromatic accent; everything else is ink on paper. */

:root {
  --background: #fafffa; /* Bone White: paper canvas, never pure #fff */
  --foreground: #000000; /* Typesetter Ink */
  --press: #121613; /* Press Black: dark sections, footer */
  --slate: #232924; /* Slate Verdant */
  --muted: #516254; /* Newsprint Gray: captions, helper text */
  --sage: #c8d2c8; /* Muted Sage: light text on dark; hairlines on light */
  --line: #d6ded6; /* hairline structure */
  --surface: #f0f6f0; /* quiet tint for hover / selected rows */
  --accent: #2bee4b; /* Highlighter Green: primary action, active underline */
  --moss: #93b799; /* Shadow Moss */
  --echo: #c4e4c9; /* Echo Green */
  --control: #7a917e; /* Control Sage: input outlines, 3.4:1 on bone (WCAG 1.4.11); hairlines stay --line */
  --control-lg: 48px; /* the primary button's height; ghost buttons beside it match */
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-press: var(--press);
  --color-slate: var(--slate);
  --color-muted: var(--muted);
  --color-sage: var(--sage);
  --color-line: var(--line);
  --color-surface: var(--surface);
  --color-accent: var(--accent);
  --color-moss: var(--moss);
  --color-echo: var(--echo);
  --color-control: var(--control);
  --spacing-control-lg: var(--control-lg);
  --font-sans: var(--font-ui);
  --font-serif: var(--font-display);
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-ui), system-ui, sans-serif;
}

/* Headlines break evenly; paragraphs avoid a lone last word. */
h1,
h2,
h3 {
  text-wrap: balance;
}
p,
li,
dd {
  text-wrap: pretty;
}

/* Browser surfaces in the palette: selection in Echo Green, the caret in ink. */
::selection {
  background: var(--echo);
  color: var(--foreground);
}
input,
textarea {
  caret-color: var(--foreground);
}

/* Small-caps micro-label: nav, buttons, section labels. */
/* DESIGN.md sets 11px / +0.01em; 12px / +0.03em keeps the broadsheet look and reads at a glance,
   which matters for the state words (Conflict, Fits your raise, Fund) set in it. */
@utility label {
  font-size: 12px;
  line-height: 1.15;
  font-weight: 550;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

/* Serif display headline: tight leading and tracking read as printed ink. */
@utility display {
  font-family: var(--font-display), Georgia, serif;
  font-weight: 400;
  line-height: 0.9;
  letter-spacing: -0.04em;
}

/* The one filled, saturated button; its shadow is green, never gray. */
@utility btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
  background: var(--accent);
  color: var(--foreground);
  min-height: var(--control-lg);
  padding: 0 28px;
  font-size: 12px;
  font-weight: 550;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  box-shadow: rgba(16, 94, 29, 0.45) 1px 8px 20px 0;
  &:disabled {
    background: transparent;
    color: var(--muted);
    box-shadow: inset 0 0 0 1px var(--line);
    cursor: not-allowed;
  }
}

/* Secondary action: ink outline, no fill, no shadow. */
@utility btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
  border: 1px solid var(--foreground);
  padding: 0 16px;
  font-size: 12px;
  font-weight: 550;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  &:hover:not(:disabled) {
    background: var(--foreground);
    color: var(--background);
  }
  &:disabled {
    opacity: 0.35;
    cursor: not-allowed;
  }
}

:focus-visible {
  outline: 2px solid var(--foreground);
  outline-offset: 2px;
}

/* Never a sideways scroll on the app's pages. */
body {
  overflow-x: clip;
}
