function Elapsed() {
  const [s, setS] = useState(0);
  useEffect(() => {
    const t = setInterval(() => setS((n) => n + 1), 1000);
    return () => clearInterval(t);
  }, []);
  if (s < 5) return null;
  return (
    <span className="whitespace-nowrap">
      ({s} s{s >= 30 ? "; questions that need Cala's sourced search can take a minute or two" : ""})
    </span>
  );
}

