}

function Score({ value }: { value: number }) {
  const v = Math.round(value);
  return (
    <div className="col-start-2 mt-4 md:col-start-auto md:mt-0 md:text-right">
      <p className="display text-4xl text-accent md:text-5xl">{v}</p>
